# Classical kernel SVM skeleton
import numpy as np
def gram(X, kernel):
    n = len(X)
    K = np.empty((n, n))
    for i in range(n):
        for j in range(n):
            K[i, j] = kernel(X[i], X[j])
    return K
# Replace `kernel` with a quantum fidelity estimator to go quantum.

