# Ring entangling layer (schematic)
def entangle_ring(n):
    for q in range(n - 1):
        qml.CNOT(wires=[q, q + 1])
    qml.CNOT(wires=[n - 1, 0])   # close the ring

# Data re-uploading on one qubit (schematic)
def reupload(x, theta, layers):
    for l in range(layers):
        qml.RX(x, wires=0)          # re-encode the input
        qml.RY(theta[l, 0], wires=0) # trainable
        qml.RZ(theta[l, 1], wires=0) # trainable
    return qml.expval(qml.PauliZ(0))

# Quantum natural gradient step (schematic)
import numpy as np
def qng_step(theta, grad, fisher, eta=0.1, reg=1e-3):
    F = fisher + reg * np.eye(len(theta))   # regularize for invertibility
    return theta - eta * np.linalg.solve(F, grad)

